function CountOccurrences(lst: seq<seq<int>>, x: int) : int
    reads lst
    ensures CountOccurrences(lst, x) == |{ (i, j) | i in 0..|lst|, j in 0..|lst[i]| && lst[i][j] == x }|
{
    var count := 0;
    var i := 0;
    while i < |lst|
        invariant 0 <= count <= i * |lst[i]| // Count does not exceed total elements considered
        invariant 0 <= i <= |lst| // i is within bounds of lst
    {
        var j := 0;
        while j < |lst[i]|
            invariant 0 <= j <= |lst[i]| // j is within bounds of lst[i]
        {
            if lst[i][j] == x {
                count := count + 1;
            }
            j := j + 1;
        }
        i := i + 1;
    }
    return count;
}

function SortedByRow(result: seq<(int, int)>) : bool
    reads result
{
    // Check if the result is sorted by the first element of tuples
    forall i: int :: 0 <= i < |result| - 1 ==> result[i][0] <= result[i + 1][0]
}

function SortedByColumn(result: seq<(int, int)>) : bool
    reads result
{
    // Check if the result is sorted by the second element of tuples within the same row
    forall i: int :: 0 <= i < |result| - 1 && result[i][0] == result[i + 1][0] ==> result[i][1] >= result[i + 1][1]
}
